"""Owner-only pilot and explicit, proof-gated SMS activation interface."""
from fastapi import APIRouter, Depends
from fastapi.responses import HTMLResponse, Response
from . import auth

router=APIRouter()


@router.get('/sms-login-test',response_class=HTMLResponse)
def page(user=Depends(auth.require_roles('owner'))):
    return HTMLResponse(PAGE,headers={'Cache-Control':'no-store','Referrer-Policy':'no-referrer'})


@router.get('/sms-login-test.js')
def script(user=Depends(auth.require_roles('owner'))):
    return Response(SCRIPT,media_type='application/javascript',headers={'Cache-Control':'no-store'})


PAGE='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>اختبار وتفعيل SMS — KPS ORDER</title><style>body{font:17px/1.8 system-ui;background:#f5f4ef;color:#222;max-width:530px;margin:30px auto;padding:24px}section,form{background:white;padding:22px;border-radius:16px;margin:18px 0}label{display:block;margin:15px 0}input,button{box-sizing:border-box;width:100%;padding:12px;font:inherit;border:1px solid #aaa;border-radius:9px}button{background:#222;color:white;cursor:pointer}#status{white-space:pre-wrap}a{color:inherit}[hidden]{display:none!important}</style>
<button type="button" id="language">English</button><h1 id="title">اختبار وتفعيل دخول SMS</h1><p id="intro">اختبار دخول حساب المالك أولًا، ثم تحقق مستقل لاعتماد التفعيل لجميع الحسابات المخولة. لا تُرسل رموز للموظفين تلقائيًا.</p><p id="mobile"></p>
<form id="prepare"><label><span id="password-label">كلمة المرور الحالية — عند طلب إعادة التحقق</span><input name="password" type="password" autocomplete="current-password"></label><button id="start">بدء اختبار دخولي وإرسال رمز SMS واحد</button></form>
<form id="login" hidden><label><span id="login-label">رمز دخول العمل من 4 أرقام</span><input name="code" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="4" required dir="ltr"></label><button id="verify-login">تحقق ودخول العمل</button></form>
<section id="sensitive" hidden><p id="sensitive-note">نجح دخول العمل. الخطوة التالية ترسل رمزًا مستقلًا لاعتماد تفعيل SMS وإلغاء دخول البريد للجميع.</p><button id="send-sensitive">إرسال رمز اعتماد التفعيل</button></section>
<form id="activate" hidden><label><span id="sensitive-label">رمز اعتماد التفعيل من 4 أرقام</span><input name="code" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="4" required dir="ltr"></label><button id="verify-activate">تحقق واعتماد التفعيل للمخولين</button></form>
<p id="status" role="status"></p><a id="back" href="/ops">العودة إلى التشغيل</a><script src="/sms-login-test.js" defer></script></html>'''


SCRIPT=r'''
let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ar',csrf='',owner=null,loginChallenge='',sensitiveChallenge='';
const tr=(ar,en)=>lang==='en'?en:ar;const status=document.getElementById('status');
function labels(){document.documentElement.lang=lang;document.documentElement.dir=lang==='en'?'ltr':'rtl';const d={title:['اختبار وتفعيل دخول SMS','Test and activate SMS sign-in'],intro:['اختبار دخول حساب المالك أولًا، ثم تحقق مستقل لاعتماد التفعيل لجميع الحسابات المخولة. لا تُرسل رموز للموظفين تلقائيًا.','Test the owner work login first, then use separate proof to activate SMS sign-in for all authorized accounts. No bulk messages are sent.'],'password-label':['كلمة المرور الحالية — عند طلب إعادة التحقق','Current password — when fresh verification is required'],start:['بدء اختبار دخولي وإرسال رمز SMS واحد','Start my login test and send one SMS code'],'login-label':['رمز دخول العمل من 4 أرقام','Four-digit work login code'],'verify-login':['تحقق ودخول العمل','Verify and sign in to work'],'sensitive-note':['نجح دخول العمل. الخطوة التالية ترسل رمزًا مستقلًا لاعتماد تفعيل SMS وإلغاء دخول البريد للجميع.','Work sign-in succeeded. The next step sends a separate code to authorize SMS activation and retire email sign-in for all authorized accounts.'],'send-sensitive':['إرسال رمز اعتماد التفعيل','Send activation authorization code'],'sensitive-label':['رمز اعتماد التفعيل من 4 أرقام','Four-digit activation authorization code'],'verify-activate':['تحقق واعتماد التفعيل للمخولين','Verify and activate for authorized accounts'],back:['العودة إلى التشغيل','Back to operations']};for(const[id,v]of Object.entries(d))document.getElementById(id).textContent=tr(...v);document.getElementById('language').textContent=lang==='ar'?'English':'العربية';}
document.getElementById('language').onclick=()=>{lang=lang==='ar'?'en':'ar';labels();};labels();
async function call(path,body){const r=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-KPS-Context':'work',...(body?{'X-CSRF-Token':csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.detail?.message||tr('تعذر إتمام الطلب.','Could not complete request.'));return d;}
async function session(){const d=await call('/api/session');if(d.user?.role!=='owner'||!d.csrf_token)throw new Error(tr('جلسة مالك مخولة مطلوبة.','An authorized owner session is required.'));owner=d.user;csrf=d.csrf_token;document.getElementById('mobile').textContent=tr('الجوال الموثق: ','Verified mobile: ')+(owner.phone?'*******'+owner.phone.slice(-3):tr('غير مسجل','Not registered'));}
session().catch(e=>{status.textContent=e.message;document.getElementById('start').disabled=true;});
document.getElementById('prepare').onsubmit=async e=>{e.preventDefault();const f=e.target,b=document.getElementById('start');b.disabled=true;status.textContent='';try{await session();if(f.elements.password.value){await call('/api/identity/step-up',{password:f.elements.password.value});f.elements.password.value='';}await call('/api/identity/owner/sms/rollout/pilot',{});const sent=await call('/api/identity/staff/code/request',{phone:owner.phone,brand_id:owner.brand_id});if(sent.channel!=='sms'||sent.code_length!==4)throw new Error(tr('لم يعتمد مسار SMS من أربع أرقام.','Four-digit SMS path was not approved.'));loginChallenge=sent.challenge_id;f.hidden=true;document.getElementById('login').hidden=false;status.textContent=tr('أدخل رمز دخول العمل الذي يصلك في الموقع.','Enter the received work login code here.');}catch(error){status.textContent=error.message;f.elements.password.value='';}finally{b.disabled=false;}};
document.getElementById('login').onsubmit=async e=>{e.preventDefault();const f=e.target,b=document.getElementById('verify-login');b.disabled=true;try{const d=await call('/api/identity/staff/code/verify',{challenge_id:loginChallenge,code:f.elements.code.value});f.elements.code.value='';if(d.user?.role!=='owner'||!d.csrf_token)throw new Error(tr('الحساب غير مخول.','Account not authorized.'));owner=d.user;csrf=d.csrf_token;f.hidden=true;document.getElementById('sensitive').hidden=false;status.textContent=tr('نجح دخول SMS الفعلي لحساب العمل؛ التفعيل العام لم يُعتمد بعد.','Real SMS work sign-in succeeded; general activation has not been authorized yet.');}catch(error){status.textContent=error.message;}finally{b.disabled=false;}};
document.getElementById('send-sensitive').onclick=async()=>{const b=document.getElementById('send-sensitive');b.disabled=true;try{const d=await call('/api/identity/owner/sms/request',{});sensitiveChallenge=d.challenge_id;document.getElementById('sensitive').hidden=true;document.getElementById('activate').hidden=false;status.textContent=tr('أدخل رمز اعتماد التفعيل؛ يختلف غرضه عن رمز الدخول.','Enter the activation authorization code; it has a separate purpose from login.');}catch(error){status.textContent=error.message;}finally{b.disabled=false;}};
document.getElementById('activate').onsubmit=async e=>{e.preventDefault();const f=e.target,b=document.getElementById('verify-activate');b.disabled=true;try{await call('/api/identity/owner/sms/verify',{challenge_id:sensitiveChallenge,code:f.elements.code.value});f.elements.code.value='';const result=await call('/api/identity/owner/sms/rollout/activate',{});if(result.mode!=='active'||result.email_retired!==true)throw new Error(tr('لم يتأكد التفعيل.','Activation not confirmed.'));f.hidden=true;status.textContent=tr('تم اعتماد دخول SMS من أربع أرقام للحسابات المخولة وإيقاف اشتراط البريد. لم تُرسل رسائل جماعية.','Four-digit SMS sign-in is active for authorized accounts and email sign-in is retired. No bulk messages were sent.');}catch(error){status.textContent=error.message;}finally{b.disabled=false;}};
'''
